    constructor(C _c) {
        c = _c;
    }

    function run(address user) public {
        bool callerIsWardBefore = c.wards(address(this)) == 1;
        uint256 userWardBefore = c.wards(user);

        bool reverted;
        try c.deny(user) {
            reverted = false;
