    function run(uint256 shares, address receiver) public payable {
        // mint requires receiver approval: msg.sender is this test contract.
        // Call mint with the given shares and receiver (caller is this contract).
        // Any revert prevented by catching? We want to test successful mint; however
        // we can catch revert and assert the successful path rule.
        // But the rule is about a call that completes.
        bool reverted;
        uint256 assetsReturned;
        try c.mint(shares, receiver) returns (uint256 assets) {
            assetsReturned = assets;
            reverted = false;
        } catch {
            reverted = true;
        }

        // The general rule: if the call succeeds, it returns exactly 0.
        // But we must end with exactly one assert and it must be general.
        // We can assert: reverted || assetsReturned == 0.
        assert(reverted || assetsReturned == 0);
    }
}

