contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 shares, address receiver, address caller) public {
        require(caller != address(this));

        uint256 supplyBefore = c.totalSupply();
        uint256 receiverBalBefore = c.balanceOf(receiver);

        bool callerIsWard = (caller == address(this)) || (c.wards(caller) == 1);
        bool reverted;

        // Drive the public entry mint via an external call from `caller` so that
        // msg.sender seen by c is `caller`, not this test contract.
        (bool ok, bytes memory ret) = address(c).call(
            abi.encodeWithSelector(C.mint.selector, receiver, shares),
            caller
        );
        reverted = !ok;

        uint256 supplyAfter = c.totalSupply();
        uint256 receiverBalAfter = c.balanceOf(receiver);

        if (!callerIsWard) {
            // An unauthorized caller must always revert with the auth guard and change nothing.
            bool revertedForAuth = reverted && ret.length >= 4 && bytes4(ret) == bytes4(keccak256("Auth/not-authorized"));
            assert(revertedForAuth && supplyAfter == supplyBefore && receiverBalAfter == receiverBalBefore);
        } else {
            // An authorized caller must not be blocked by the auth guard.
            bool revertedForAuth = reverted && ret.length >= 4 && bytes4(ret) == bytes4(keccak256("Auth/not-authorized"));
            assert(!revertedForAuth);
        }
    }

    receive() external payable {}
}

