        } catch {
            wardCaller = 0;
        }
        // After deny, caller is not authorized.
        require(wardCaller == 0);

        bool reverted;
        try c.burn(user, value) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: burn must revert for an unauthorized caller.
        assert(reverted);
    }

    receive() external payable {}
}

