contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint256 shares, address receiver) public {
        // reset the caller-controlled state: make receiver the caller itself so
        // the withApproval check mirrors P's authorization rule
        address owner = address(this);

        bool wasAuthorized = false;
        // only query authorization through public surface; receiver is the owner
        // in these entry points, so try to align it with msg.sender
        if (receiver == owner) {
            wasAuthorized = true;
        }

        uint256 previewAssetsBefore;
        bool previewReverted;
        try c.previewMint(shares) returns (uint256 assets) {
            previewAssetsBefore = assets;
            previewReverted = false;
        } catch {
            previewReverted = true;
        }

        bool mintReverted;
        uint256 mintAssets;
        if (receiver == owner) {
            try c.mint(shares, receiver) returns (uint256 assets) {
                mintAssets = assets;
                mintReverted = false;
            } catch {
                mintReverted = true;
            }
        } else {
            // unauthorized path: mint is guaranteed to revert
            mintReverted = true;
            mintAssets = 0;
        }

        bool previewStable = !previewReverted && !mintReverted && previewAssetsBefore == mintAssets;
        bool previewMatchesRevert = previewReverted == mintReverted;

        assert(previewMatchesRevert || previewStable);
    }

    receive() external payable {}
}

