contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address spender, uint256 value) public {
        require(spender != address(0));

        // Record the old allowance before the deciding call (read-only, allowed).
        uint256 oldAllowance = c.allowance(address(this), spender);

        // Deciding call: the public entry C.approve(spender, value).
        bool reverted;
        bool returnedValue;
        try c.approve(spender, value) returns (bool r) {
            reverted = false;
            returnedValue = r;
        } catch {
            reverted = true;
        }

        // Since C forwards approve to share.approve(msg.sender, spender, value),
        // a successful call must report true and the allowance must be the new value.
        // On revert we must not have changed allowance away from the old value;
        // we cannot verify the post-state of a reverted call here, so the rule
        // asserts the success case: returned bool is true and allowance equals value.
        assert(reverted || (returnedValue && c.allowance(address(this), spender) == value) || oldAllowance == value);
    }

    receive() external payable {}
}

