        // msg.sender is this test contract, which deployed c and is therefore an initial ward.
        bool callerIsWard = (c.wards(address(this)) == 1);

        uint256 targetBefore = c.wards(target);
        uint256 callerBefore = c.wards(address(this));

        // Make target a ward so we can observe the effect of denying it.
        if (callerIsWard) {
            c.rely(target);
            require(c.wards(target) == 1, "target must be ward");
            targetBefore = 1;
        }

        bool reverted;
        try c.deny(target) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (callerIsWard) {
            assert(!reverted && c.wards(target) == 0 && c.wards(address(this)) == callerBefore);
        } else {
            assert(reverted && c.wards(target) == targetBefore && c.wards(address(this)) == callerBefore);
        }
    }

    receive() external payable {}
}

